	##############################################################################
	def convertDatasetToDict(data, keyCol, valueCol):
		'''
			Given the name of a key column and value column, this function will convert a dataset into a dictionary of key value pairs (kanoaCore)
			if valueCol is None, all data columns will be returned as values for each key

			Args:
				data: pyDataset or basic dataset
				keyCol: string i.e. 'configName'
				keyValue: string i.e. 'configValue' or null to return all column values in the dictionary
			returns:
				dictionary
			Updated:
				jfc - 11/22/23 9:12am Created
				jfc - 11/28/24 7:31am Updated to allow for multiple values to be retunred for a key
		'''

		if valueCol:
			data = system.dataset.toPyDataSet(system.dataset.filterColumns(data, [keyCol, valueCol]))
			return {row[keyCol]: row[valueCol] for row in data}
		else:
			myDict = {}
			cols = system.dataset.getColumnHeaders(data)
			for row in data:
				rowDict = {}
				for i, value in enumerate(row):
					rowDict[cols[i]] = value

				myDict[row[keyCol]] = rowDict

			return myDict

#	return system.kanoa.utilities.convertDatasetToDict(system.kanoa.quality.config.getCheckItemStates({'enabled': True}), 'chkItemStateName', None)
	return convertDatasetToDict(system.kanoa.quality.config.getCheckItemStates({'enabled': True}), 'chkItemStateName', None)

