	def buildCell(cellValue, editable, required, chkItemType):
		cellHeight = '50px' if self.view.custom.displaySettings.touchFriendly else '28px'
		mh = '2px' if self.view.custom.displaySettings.touchFriendly else '1px'

		if chkItemType == 'Calculated': style = {"margin-top": mh, "margin-bottom": mh, "margin-right": mh, "textAlign": "center", "height": cellHeight, "fontStyle": "italic"	}
		elif editable:
			style = {
					  "borderStyle": "solid",
					  "borderWidth": "2px" if required else '1px',
					  "borderColor": self.view.custom.displaySettings.reqdChkColor if required else "--kcGray-50",
					  "borderTopLeftRadius": "4px",
					  "borderTopRightRadius": "4px",
					  "borderBottomLeftRadius": "4px",
					  "borderBottomRightRadius": "4px",
					  "margin-top": mh,
					  "margin-bottom": mh,
					  "margin-right": mh,
					  "textAlign": "center",
					  "height": cellHeight 
					}
		elif required: style = {"margin-top": mh, "margin-bottom": mh, "margin-right": mh, "textAlign": "center", "height": cellHeight}
		else: style = {"margin-top": mh, "margin-bottom": mh, "margin-right": mh, "textAlign": "center", "height": cellHeight}

		return {"value": cellValue, "editable": editable, "style": style}

	groupName = self.custom.table.groups[self.custom.table.tabIndex]
	data = value['chkShtData']

	if len(data) == 0: return []	#No data

	table = []
	maxMeasCount = max([row['measCount'] for row in data])	#We have to add a column for all measurements counts, even if this chktem only has one measurement count for the measCount columns to show in the table

	for row in data:
		if row['chkItemGroupName'] != groupName and groupName != 'All': continue 

		tableRow = dict(row)
		foundRow = [element for element in table if element['chkItemId'] == row['chkItemId']]

		if len(foundRow) == 0:	#Haven't created this yet
			tableRow['reqdIcon'] = u'☆' if row['required'] else ''
			displayName = row['chkItemGroupName'] + ' > ' + row['chkItemName'] if groupName == 'All' else row['chkItemName']

			if row['chkItemTypeName'] in ('Calculated', 'Trigger') or row['chkItemTriggerId'] is not None:
				if row['chkItemTypeName'] == 'Calculated': displayName += ' (∑)'
				elif row['chkItemTypeName'] == 'Trigger': displayName += ' (Ţ)'
				elif row['chkItemTriggerId'] is not None: displayName += ' (Ť)'
			tableRow['displayName'] = displayName

			editable = False if row['chkItemTypeName'] == 'Calculated' else True
			valBool = True if editable and row['dataTypeName'] == 'Boolean' else False	#Convert boolean datatypes to a checkbox in the table
			for i in range(1, maxMeasCount+1):
				makeEditable = editable and i <= row['measCount']
				tableRow['_%s'%(i)] = buildCell(None, makeEditable, row['required'], row['chkItemTypeName'])
			tableRow['sum'] = None
			tableRow['min'] = None
			tableRow['max'] = None
			tableRow['avg'] = None
			tableRow['stdDev'] = None
			tableRow['range'] = None

			tableRow['pickListValues'] = system.util.jsonDecode(row['pickListValues'])
		else:
			tableRow = foundRow[0]

		if row['measNumber'] is not None:
			value = system.kanoa.utilities.formatNumber(row['format'], row['chkItemValue']) if row['format'] is not None else row['chkItemValue']
			tableRow['_%s'%row['measNumber']] = buildCell(value, editable, row['required'], row['chkItemTypeName'])
			tableRow['_%s'%row['measNumber']]['style']['backgroundColor'] = row['chkItemStateColor']
			#tableRow['_%s'%row['measNumber']]['style']['color'] = system.kanoa.utilities.getContrastingColor(row['chkItemStateColor'])

		if row['measCount'] > 1 and row['dataTypeName'] in ('Float', 'Integer'):
			measAggregate = row['measAggregate'] or 'AVG'
#			system.perspective.print("measAggregate = %s"%row['measAggregate'])
			measStyle = {"editable": False}
			measAggStyle = {"editable": False, "borderStyle": "solid", "fontWeight": "bold", "borderWidth": "1px", "borderTopLeftRadius": "10px", "borderTopRightRadius": "10px","borderBottomLeftRadius": "10px", "borderBottomRightRadius": "10px"}
			try:
				valuesList = [float(tableRow['_%s'%i]['value']) for i in range(1, maxMeasCount+1) if tableRow['_%s'%i]['value'] is not None]
				measSum = system.math.sum(valuesList)
				measMin = system.math.min(valuesList)
				measMax = system.math.max(valuesList)
				measAvg = system.math.mean(valuesList)
				measStdDev = system.math.standardDeviation(valuesList)
				measRange = max(valuesList) - min(valuesList) if len(valuesList) > 0 else None
				tableRow['sum'] = {"value": measSum, "style": measAggStyle if 'SUM' == measAggregate else measStyle}
				tableRow['min'] = {"value": measMin, "style": measAggStyle if 'MIN' == measAggregate else measStyle}
				tableRow['max'] = {"value": measMax, "style": measAggStyle if 'MAX' == measAggregate else measStyle}
				tableRow['avg'] = {"value": measAvg, "style": measAggStyle if 'AVG' == measAggregate else measStyle}
				tableRow['stdDev'] = {"value": measStdDev, "style": measAggStyle if 'STDDEV' == measAggregate else measStyle}
				tableRow['range'] = {"value": measRange, "style": measAggStyle if 'RANGE' == measAggregate else measStyle}
			except:
				pass			

		if len(foundRow) == 0:	table.append(tableRow)

	self.view.custom.table.maxMeasCount = maxMeasCount

	return table


