onChange.script:

#	system.perspective.print("currentValue is %s"%currentValue.value)

	if not self.view.custom.chkSht.info.has_key('chkShtStateName') or self.view.custom.chkSht.info.chkShtStateName == 'Approved':
		self.custom.clear = True
		return

	data = self.props.data
	if len(data) == 0: 	
		self.view.custom.inputValue = ''
		return

	lastChar = data[len(data)-1]	
	if len(lastChar) > 1:
#		system.perspective.print("Special Char %s"%lastChar)	
		if lastChar == 'Enter': 
			self.view.getChild("root").sendValue()
			return
		elif lastChar == 'Backspace': #system.perspective.print("deleting last entry")
			if len(self.view.custom.userInput.inputValue) > 0: self.view.custom.userInput.inputValue = self.view.custom.userInput.inputValue[:-1]
		elif lastChar == 'Delete':	system.perspective.sendMessage("ValuePicked", {'value':None})
		elif lastChar == 'ArrowDown': self.view.getChild("root").selectCheck('Down')
		elif lastChar == 'ArrowUp': self.view.getChild("root").selectCheck('Up')
		elif lastChar == 'ArrowLeft': self.view.getChild("root").selectCheck('Left')
		elif lastChar == 'ArrowRight': self.view.getChild("root").selectCheck('Right')

		return

	if self.view.custom.userInput.inputValue is None: self.view.custom.userInput.inputValue = ''
	self.view.custom.userInput.inputValue += lastChar

	return

customMethods.script:

#	system.perspective.print("updateCheckCalculation() called for %s"%chkItem['chkItemName'])

	chkShtEventId = self.view.custom.chkSht.info.chkShtEventId
	tableData = self.view.custom.table.chkShtData
	calculation = system.util.jsonDecode(chkItem['calculation'])

	if calculation is None: return None

	calc = calculation['formulaType']
	formula = calculation['values']
	script = calculation['script']

	if formula:
		chkItemPaths = ["%s\%s"%(chkItem['chkItemGroupName'], chkItem['chkItemName']) for chkItem in tableData if "'" + "%s\%s"%(chkItem['chkItemGroupName'], chkItem['chkItemName']) + "'" in formula]	#pulls the check name out of the formula
		chkItemValues = system.kanoa.utilities.convertDatasetToDict(system.kanoa.quality.event.getAllChkShtItemEventValues(chkShtEventId, chkItemPaths), 'chkItemPath', 'chkItemValue')
	else:
		chkItemValues = {}

	if calc == 'SCRIPT':
		args = {'productId':self.view.custom.chkSht.info.itemId}
		args['measurements'] = chkItemValues
		args['chkShtInfo'] = self.view.custom.chkSht.info
#		system.perspective.print("func is %s. Args are %s"%(script, args)) #args = {'M09':0.56, 'M01':0.58, 'M02':None, 'M03':0.48, 'M04':None, 'M00':0.6}
		calcValue, msg = kanoaScripts.custom.quality.calculators.executeCalculator(script, args)


	elif calc == 'EVAL':	#This is a custom calculation i.e EVAL(7 + 5 * 4.2/3).	We need to pull out the chkItemNames and replace them with the actual value
		for k,v in chkItemValues.items():
			formula = formula.replace("'" + k + "'", str(v))

#		system.perspective.print("Found item %s with value %s, Formula is now %s "%(chkItem['chkItemName'], chkItemValues[chkItem['chkItemName']], formula))
		try:
			calcValue = eval(formula)
		except:	
			system.perspective.print("error with eval")
			calcValue = None

	else:	#(min, max, avg, etc.)
		if len(chkItemValues) == 0: calcValue = None
		elif calc == 'AVG': calcValue = system.math.mean(chkItemValues.values())
		elif calc == 'STDDEV': calcValue = system.math.standardDeviation(chkItemValues.values())
		elif calc == 'SUM': calcValue = system.math.sum(chkItemValues.values())					
		elif calc == 'MIN': calcValue = system.math.min(chkItemValues.values())
		elif calc == 'MAX': calcValue = system.math.max(chkItemValues.values())
		elif calc == 'RANGE': 	
			try:
				calcValue = system.math.max(chkItemValues.values()) - system.math.min(chkItemValues.values())
			except:
				system.perspective.print("error with range")
				pass
		else: calcValue = None

	system.perspective.print("updateCheckCalculation() returned %s"%calcValue)

	return calcValue

messageHandlers.script:
	def endFunction(msg, level='info'):
		if msg is not None: 
			system.perspective.print("%s"%msg)
			if level == 'info': toast = 'showInfoToast'
			elif level == 'warn': toast = 'showWarningToast'
			elif level == 'error': toast = 'showFailerToast'
			else: toast = 'showInfoToast'

			system.perspective.sendMessage(toast, {'message': msg})

		self.view.refreshBinding("custom.table.chkShtData")
		self.view.custom.displaySettings.lockEditing = False
		return

	system.perspective.print("Received ValuePicked message with %s"%payload)
	self.view.custom.userInput.inputValue = '' #Clear keyboard value
	sel = self.view.custom.table.selection
	selectedRow = sel.row
	selectedColName = sel.col or '_1'
	chkItems = sel.chkItems
	msgLevel = 'warn'
	chkItemStates = self.view.custom.chkItemStates

	reqdCommentChks = []	#Holds a list of check items that failed and are required, in which case we will ask for a comment to be entered

#	system.perspective.print("chkItems %s"%chkItems)

	if not self.view.custom.displaySettings.editMode:
		system.perspective.print("Check Sheet is not in the right status to be updated. Exiting....")
		return #endFunction("Check Sheet is not in the right status to be updated. Exiting....")
	if self.view.custom.displaySettings.lockEditing: 
		system.perspective.print("Locked FOR EDITING. Exiting....")
		self.view.custom.displaySettings.lockEditing = False
		return	#system.perspective.print("Locked FOR EDITING. Exiting....")
	if len(chkItems) == 0: 
		system.perspective.print("No chkItems selected, Exiting....")
		return 	#system.perspective.print("No chkItems selected, Exiting....")
	if self.view.custom.chkSht.info.chkShtStateName == 'Approved': 
		system.perspective.print("Chk Sheet status is approved. Exiting....")
		return

	value = payload['value']
	self.view.custom.displaySettings.lockEditing = True

	if selectedColName == 'comment':
		for chkItem in chkItems:
			chkItemEventInfo = {'chkItemEventId': chkItem['chkItemEventId'], 'comment':value} if chkItem['chkItemEventId'] is not None else {'chkShtEventId': chkItem['chkShtEventId'], 'chkItemId': chkItem['chkItemId'], 'measNumber': chkItem['measNumber'], 'comment':value}
			system.kanoa.quality.event.addChkItemEventComment(chkItemEventInfo, self.view.custom.security.userId)

		self.view.refreshBinding("custom.table.chkShtData")	
		endFunction("Comments added")
		return

	for chkItem in chkItems:
		#Let's do some data validation on the required type and value being entered

		if chkItem['chkItemTypeName'] == 'Calculated': continue	#Can't be added manually, we check at the end for updates to calculators

		if value is None:	#user is clearing the value
			chkShtItemEventInfo = {'chkShtEventId': chkItem['chkShtEventId'], 'chkItemEventId': chkItem['chkItemEventId']}
			if selectedColName != 'displayName': chkShtItemEventInfo['measNumber'] = int(selectedColName.replace('_',''))
			self.deleteChkItems	(chkShtItemEventInfo)
		elif chkItem['pickListName'] == 'Time':	#special case here, value is returned in format of 'hhmmss'. we'll convert it to seconds
			val = str(value).zfill(6)
			value = int(val[:2]) * 3600 + int(val[2:4]) * 60 + int(val[4:6])		
		elif chkItem['dataTypeName'] == 'Boolean':
			try: 
				if int(value) not in (0,1):
					endFunction("Check Value must be 1 or 0.", 'warn')
					return
			except:
				endFunction("Check Value must be 1 or 0.", 'warn')
				return
		elif chkItem['dataTypeName'] in ('Integer', 'Float'):
			try:
				value = float(value)
			except:	
				endFunction("Check Value must be numeric.", 'warn')
				return	

			if chkItem['dataTypeName'] == 'Integer' and int(value) != value:	#Going to check here if someone has entered a real with decimal place and let them know prior to entering it
				endFunction("This checks requires a whole number. You entered a decimal.", 'warn')
				return
		elif chkItem['pickListName'] == 'Barcode Scanner' and chkItem['pickListValues'] is not None:	
			args = {}
			measurements = {}
#			system.perspective.print("Barcode scanner has script")
			pickListValues = system.util.jsonDecode(chkItem['pickListValues'])
			script = pickListValues['script']
			if script is None:
				system.perspective.sendMessage('showWarningToast', {'message': "No script configured for this check item"})
			else:
				args['measurements'] = {'1': value}
#				system.perspective.print("func is %s. Args are %s"%(script, args))
				value, msg = kanoaScripts.custom.quality.calculators.executeCalculator(script, args)
				if msg: system.perspective.sendMessage('showFailerToast', {'message': "%s returned error %s"%(script, msg)})
		elif chkItem['dataTypeName'] == 'String' and chkItem['specification']:
			spec = system.util.jsonDecode(chkItem['specification'])
			import re
			if not bool(re.match(spec['regex']['value'], value)):
				endFunction("Value %s does not match regex %s"%(value, spec['regex']['value']), 'warn')
				return

		chkItemStateId, chkItemStateValue, msg = self.getChkItemStateId(dict(chkItem), value, chkItemStates)
		if msg is None:
			if chkItem['chkItemId'] == self.view.custom.chkSht.info.takenDateChkItemId and value is not None: 
				self.view.custom.chkSht.info.takenDate = system.date.parse(value, 'yyyy-MM-dd hh:mm')
			elif self.view.custom.chkSht.info.takenDate is None: self.view.custom.chkSht.info.takenDate = system.date.now()

			#Normally a measurment column will be selected but if the user wants all the measurements to receive the same value, then the selection data will contain the row displayName
			if selectedColName == 'displayName': measurements = [i for i in range(1, chkItem['measCount'] + 1)]
			elif '_' in selectedColName: measurements = [int(selectedColName.replace('_',''))]
			else: measurements = [1]

			for measNum in measurements:
				if chkItem['pickListValues'] and isinstance(chkItem['pickListValues'], dict) and chkItem['pickListValues'].has_key('multiSelect') and chkItem['pickListValues']['multiSelect']: 
					if value not in (chkItem[selectedColName]['value'] or ''): 
						value = chkItem[selectedColName]['value'] + ',' + value if chkItem[selectedColName]['value'] else value
						msgLevel = 'info'
						msg = 'This is a multi-select check item.'
					else:
						msg = 'This value has already been selected'
						continue

				chkItemEventInfo = {'chkShtEventId':chkItem['chkShtEventId'], 'chkItemEventId': None, 'chkItemId': chkItem['chkItemId'], 'measNumber': measNum, 'chkItemValue': value, 'chkItemStateId': chkItemStateId}

				chkItemEventId = system.kanoa.quality.event.saveChkItemEvent(chkItemEventInfo, self.view.custom.security.userId)

				if chkItemEventId is None: system.perspective.sendMessage('showFailerToast', {'message': "Failed to save the last check value %s)"%chkItemEventInfo})
				else: 
					system.perspective.sendMessage('showInfoToast', {'message': "%s value has been updated"%chkItem['chkItemName']})
					if chkItem['required'] and chkItemStateValue == 'FAIL': reqdCommentChks.append(chkItemEventId)

		self.view.refreshBinding("custom.table.chkShtData")
		if len(chkItems) == 1 and chkItem['chkItemTypeName'] == 'Trigger': 
			triggeredChkItems = self.updateTriggerChkItems(chkItem, value)	#only do a trigger update if only one row has been selected
			for chkItem in triggeredChkItems: self.updateCheckCalculations(chkItem)			

		self.updateCheckCalculations(chkItem)

	endFunction(msg, msgLevel)

	if len(reqdCommentChks) > 0: system.perspective.openPopup('enterFailedCheckComment', 'kanoa/qds/schedule/popups/failedChecks', params={'values': {'chkItemEventIdList': reqdCommentChks}}, title='Failed Check Comments', resizable=True, draggable=True, viewportBound=True)

	elif not msg: self.selectNextCheck(selectedRow, selectedColName)

	return


system.perspective.print("Received deleteCheckAllChecks message with " + str(payload)) 
if payload.has_key('userInput') and payload['userInput'] == 'OK':
	chkShtEventInfo = {'chkShtEventId':self.view.params.chkShtEventId}
	groupName = self.view.custom.table.groups[self.view.custom.table.tabIndex]
